// GeneratedNotice is the line every generated chapter carries near the top.
// TestGeneratedDocsSaySoAtTheTop in internal/docsaudit looks for the words
// "Generated by tools/", so this says it in the same terms the other
// generated pages do.
const GeneratedNotice = "<!-- Generated by tools/handbook. Edit the code, not this file. -->"

// Group is a run of packages that one generated chapter covers.
type Group struct {
	// File is the chapter, relative to docs/handbook.
	File  string
	Title string
	// Intro is hand-written orientation in front of the generated entries:
	// the one place a person says how the packages fit together.
	Intro string
	// Packages are directories relative to the repository root.
	Packages []string
}

