// EveryPackage lists the Go packages of the repository that are documented:
// the directories under cmd, ext, internal and tools that hold Go source.
func EveryPackage(root string) ([]string, error) {
	var out []string
	for _, top := range []string{"cmd", "ext", "internal", "tools"} {
		base := filepath.Join(root, top)
		err := filepath.WalkDir(base, func(p string, d os.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if !d.IsDir() {
				return nil
			}
			if d.Name() == "testdata" || strings.HasPrefix(d.Name(), ".") {
				return filepath.SkipDir
			}
			ents, err := os.ReadDir(p)
			if err != nil {
				return err
			}
			for _, e := range ents {
				if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
					rel, _ := filepath.Rel(root, p)
					out = append(out, filepath.ToSlash(rel))
					break
				}
			}
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	sort.Strings(out)
	return out, nil
}

// CheckGroups returns what is wrong with the assignment of packages to
// chapters: a package no chapter describes, one described twice, and one that
// is named and does not exist.
func CheckGroups(root string) []string {
	have, err := EveryPackage(root)
	if err != nil {
		return []string{err.Error()}
	}
	exists := map[string]bool{}
	for _, p := range have {
		exists[p] = true
	}
	seen := map[string]string{}
	var bad []string
	for _, g := range Groups {
		for _, p := range g.Packages {
			if prev, dup := seen[p]; dup {
				bad = append(bad, fmt.Sprintf("%s is described by both %s and %s", p, prev, g.File))
			}
			seen[p] = g.File
			if !exists[p] {
				bad = append(bad, fmt.Sprintf("%s names %s, which is not a package", g.File, p))
			}
		}
	}
	for _, p := range have {
		if _, ok := seen[p]; !ok {
			bad = append(bad, fmt.Sprintf("%s is in no group of internal/handbook.Groups; add it to the chapter it belongs in", p))
		}
	}
	return bad
}

const importBase = "github.com/edlitmus/halite/"

// PackageChapter renders one group.
func PackageChapter(root string, g Group) (string, error) {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", g.Title)
	b.WriteString(GeneratedNotice + "\n\n")
	b.WriteString("<!-- kind: reference -->\n\n")
	b.WriteString(g.Intro + "\n\n")
	b.WriteString("Each entry below is the package's own documentation comment, unedited, followed by\n" +
		"the files it is made of and what it exports. The comments in this codebase are long on\n" +
		"purpose: they say why, and why the obvious alternative is wrong.\n\n")
	for _, dir := range g.Packages {
		sec, err := packageSection(root, dir)
		if err != nil {
			return "", err
		}
		b.WriteString(sec)
	}
	return b.String(), nil
}

func packageSection(root, dir string) (string, error) {
	fset := token.NewFileSet()
	abs := filepath.Join(root, filepath.FromSlash(dir))
	pkgs, err := parser.ParseDir(fset, abs, nil, parser.ParseComments)
	if err != nil {
		return "", fmt.Errorf("%s: %w", dir, err)
	}
	// A directory can hold a package and its external test package, and
	// nothing else. Choose the one that is not the _test package.
	var name string
	for n := range pkgs {
		if !strings.HasSuffix(n, "_test") {
			name = n
		}
	}
	if name == "" {
		return "", fmt.Errorf("%s: no package found", dir)
	}
	pkg := pkgs[name]

	var files, testFiles []string
	for fn := range pkg.Files {
		base := filepath.Base(fn)
		if strings.HasSuffix(base, "_test.go") {
			testFiles = append(testFiles, base)
		} else {
			files = append(files, base)
		}
	}
	sort.Strings(files)
	sort.Strings(testFiles)

	// The declarations documented are those of one platform's build.
	// ParseDir reads every file whatever its build constraints, so a
	// function defined once for Unix and once for Windows is two
	// declarations, and which one go/doc keeps depends on map order:
	// the chapter then differed from run to run. Choosing the files the
	// linux/amd64 build would compile (and, for a package with none, the
	// windows/amd64 build) makes the output a function of the source.
	nontest := map[string]*ast.File{}
	for _, goos := range []string{"linux", "windows", "darwin"} {
		ctx := build.Default
		ctx.GOOS, ctx.GOARCH, ctx.CgoEnabled = goos, "amd64", false
		for fn, f := range pkg.Files {
			base := filepath.Base(fn)
			if strings.HasSuffix(base, "_test.go") {
				continue
			}
			if ok, err := ctx.MatchFile(filepath.Dir(fn), base); err == nil && ok {
				nontest[fn] = f
			}
		}
		if len(nontest) > 0 {
			break
		}
	}

	// The package comment: from the product files if there is one, and
	// otherwise from the test files, because several of the audit packages
	// are tests and nothing else.
	docText := ""
	d := doc.New(&ast.Package{Name: name, Files: nontest}, importBase+dir, 0)
	docText = d.Doc
	if strings.TrimSpace(docText) == "" {
		for _, fn := range sortedKeys(pkg.Files) {
			if f := pkg.Files[fn]; f.Doc != nil && strings.HasSuffix(fn, "_test.go") {
				docText = f.Doc.Text()
				break
			}
		}
	}
	if strings.TrimSpace(docText) == "" {
		return "", fmt.Errorf("%s has no package documentation; add a doc.go that says what the package is for", dir)
	}

	var b strings.Builder
	fmt.Fprintf(&b, "## `%s`\n\n", dir)
	if name == "main" {
		b.WriteString("A command. ")
	}
	fmt.Fprintf(&b, "Import path `%s`.\n\n", importBase+dir)

	var pr comment.Printer
	pr.HeadingLevel = 3
	parsed := (&comment.Parser{}).Parse(docText)
	md := string(pr.Markdown(parsed))
	md = demoteHeadings(md)
	b.WriteString(strings.TrimRight(md, "\n") + "\n\n")

	fmt.Fprintf(&b, "**Files:** %s", codeList(files))
	if len(testFiles) > 0 {
		// Whether there are tests, not how many files hold them: a count
		// would put a stale-chapter failure on every change that adds a
		// test file, which is the change least worth interrupting.
		b.WriteString("; with tests")
	}
	b.WriteString(".\n\n")

	if name != "main" {
		b.WriteString(exportedLines(d))
	}
	return b.String(), nil
}

// demoteHeadings makes every heading inside a package comment a level-three
// heading, directly below the package's own level-two heading, so that the
// chapter's outline is one a reader can navigate and the heading-level check
// accepts. It also drops the explicit anchor ({#hdr-…}) the Go Markdown
// printer appends: the renderer derives its own, the same way GitHub does.
func demoteHeadings(md string) string {
	var out []string
	inFence := false
	for _, line := range strings.Split(md, "\n") {
		if strings.HasPrefix(strings.TrimSpace(line), "```") {
			inFence = !inFence
		}
		if !inFence && strings.HasPrefix(line, "#") {
			trimmed := strings.TrimLeft(line, "#")
			if strings.HasPrefix(trimmed, " ") {
				text := strings.TrimSpace(trimmed)
				if i := strings.Index(text, " {#hdr-"); i >= 0 && strings.HasSuffix(text, "}") {
					text = text[:i]
				}
				line = "### " + text
			}
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

func codeList(names []string) string {
	q := make([]string, len(names))
	for i, n := range names {
		q[i] = "`" + n + "`"
	}
	return strings.Join(q, ", ")
}

func sortedKeys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// exportedLines lists the exported types and functions with the first
// sentence of each one's documentation. It is bounded, because a package of
// two hundred exported names is better read in the source.
func exportedLines(d *doc.Package) string {
	const limit = 60
	type item struct{ name, kind, syn string }
	var items []item
	for _, t := range d.Types {
		items = append(items, item{t.Name, "type", d.Synopsis(t.Doc)})
		for _, f := range t.Funcs {
			items = append(items, item{f.Name, "func", d.Synopsis(f.Doc)})
		}
	}
	for _, f := range d.Funcs {
		items = append(items, item{f.Name, "func", d.Synopsis(f.Doc)})
	}
	if len(items) == 0 {
		return ""
	}
	sort.SliceStable(items, func(i, j int) bool { return items[i].name < items[j].name })
	var b bytes.Buffer
	b.WriteString("**Exports.**\n\n")
	for i, it := range items {
		if i == limit {
			fmt.Fprintf(&b, "- … and %d more; see the source.\n", len(items)-limit)
			break
		}
		if it.syn != "" {
			fmt.Fprintf(&b, "- `%s` (%s): %s\n", it.name, it.kind, oneLine(it.syn))
		} else {
			fmt.Fprintf(&b, "- `%s` (%s)\n", it.name, it.kind)
		}
	}
	b.WriteString("\n")
	return b.String()
}

func oneLine(s string) string {
	s = strings.Join(strings.Fields(s), " ")
	// Table-safe and Markdown-safe: a stray pipe or underscore pair in a
	// synopsis is not a reason to fail the chapter.
	return s
}

// Binaries are the programs whose command line the reference reproduces.
var Binaries = []string{"halite-node", "halite-hub", "halite-api"}

// CLIChapter renders the command-line reference from the binaries' own help.
// It runs them with `go run` so that the text is the one in the source, and
// the test that compares it with the committed chapter is therefore a test
// that the documentation and the dispatch switch say the same thing.
func CLIChapter(root string) (string, error) {
	var b strings.Builder
	b.WriteString("# Command-line reference\n\n")
	b.WriteString(GeneratedNotice + "\n\n")
	b.WriteString("<!-- kind: reference -->\n\n")
	b.WriteString("The three programs, as they describe themselves. Everything below is the output of\n" +
		"`<program> help`, taken from the source when this chapter was generated, so a command\n" +
		"or flag that exists is listed here and one that does not is not. For the manual pages\n" +
		"that ship in every release, `man 8 halite-node`, `man 8 halite-hub` and `man 8 halite-api`\n" +
		"have the same commands with their prose, and `man 7 halite` is the overview.\n\n")
	for _, bin := range Binaries {
		cmd := exec.Command("go", "run", "./cmd/"+bin, "help")
		cmd.Dir = root
		cmd.Env = append(os.Environ(), "GOFLAGS=-mod=vendor", "GOPROXY=off")
		var stdout, stderr bytes.Buffer
		cmd.Stdout, cmd.Stderr = &stdout, &stderr
		if err := cmd.Run(); err != nil {
			return "", fmt.Errorf("%s help: %v\n%s", bin, err, stderr.String())
		}
		fmt.Fprintf(&b, "## %s\n\n```\n%s```\n\n", bin, stdout.String())
	}
	return b.String(), nil
}

// Contents renders docs/handbook/README.md: the table of contents, for
// someone reading on GitHub rather than in the HTML edition.
func Contents(bk *Book) string {
	var b strings.Builder
	b.WriteString("# The halite Handbook\n\n")
	b.WriteString(GeneratedNotice + "\n\n")
	b.WriteString("This directory is the handbook: a complete guide to halite for someone who has never\n" +
		"seen it, from what it is and why, through writing and running a fleet's configuration,\n" +
		"to the runbooks for operating it, the reference, and the code. It is part of every\n" +
		"release (the archives carry it as HTML and Markdown), and the tests that keep it\n" +
		"honest are described in the chapter on how it is built.\n\n")
	b.WriteString("To read it as a book, open `index.html` from the handbook directory of a release\n" +
		"archive, or build it with `make handbook` and open `build/handbook/index.html`. The\n" +
		"index is `genindex.html`, and `handbook.html` is the whole book on one page.\n\n")
	for _, p := range bk.Parts {
		fmt.Fprintf(&b, "## %s\n\n", p.Title)
		for _, c := range p.Chapters {
			title := chapterTitle(c)
			link := strings.TrimPrefix(c.Source, "docs/handbook/")
			if strings.HasPrefix(c.Source, "docs/") && !strings.HasPrefix(c.Source, "docs/handbook/") {
				link = "../" + strings.TrimPrefix(c.Source, "docs/")
			} else if !strings.HasPrefix(c.Source, "docs/") {
				link = "../../" + c.Source
			}
			num := ""
			if c.Number > 0 {
				num = fmt.Sprintf("%d. ", c.Number)
			}
			line := fmt.Sprintf("- %s[%s](%s)", num, title, link)
			if c.Doc != nil {
				if a := abstractOf(c.Doc); a != "" {
					line += " — " + a
				}
			}
			b.WriteString(line + "\n")
		}
		b.WriteString("\n")
	}
	return b.String()
}

// Generate returns every generated file, keyed by repository-relative path.
func Generate(root string) (map[string]string, error) {
	out := map[string]string{}
	if bad := CheckGroups(root); len(bad) > 0 {
		return nil, fmt.Errorf("the package groups are wrong:\n  %s", strings.Join(bad, "\n  "))
	}
	for _, g := range Groups {
		s, err := PackageChapter(root, g)
		if err != nil {
			return nil, err
		}
		out["docs/handbook/"+g.File] = s
	}
	cli, err := CLIChapter(root)
	if err != nil {
		return nil, err
	}
	out["docs/handbook/gen-cli.md"] = cli

	// The contents file is generated last, from the book as it will be once
	// these files exist. ReadContents needs them on disk to render titles, so
	// the caller writes the others first and then asks for this one.
	return out, nil
}
